import { ref, onMounted } from 'vue';
import * as echarts from 'echarts';
import axios from 'axios';
import { API_CONFIG } from './config';
export default {
  __name: 'UserDashboard',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const genderChart = ref(null);

    // 获取并渲染性别分布数据
    const renderGenderChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/gender-distribution`);
        const data = response.data;
        const chart = echarts.init(genderChart.value);
        const option = {
          title: {
            text: '性别比例分布',
            subtext: `总人数: ${data.total}`,
            left: 'center'
          },
          tooltip: {
            trigger: 'item',
            formatter: params => {
              return `${params.seriesName}<br/>${params.name}: ${params.value}人 (${params.percent}%)`;
            }
          },
          legend: {
            orient: 'vertical',
            left: 'left',
            data: ['男', '女']
          },
          series: [{
            name: '性别分布',
            type: 'pie',
            radius: ['40%', '70%'],
            avoidLabelOverlap: false,
            itemStyle: {
              borderRadius: 10,
              borderColor: '#fff',
              borderWidth: 2
            },
            label: {
              show: true,
              formatter: '{b}: {d}%' // 显示名称和百分比
            },
            emphasis: {
              label: {
                show: true,
                fontSize: '18',
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: true
            },
            data: [{
              value: data.male_count,
              name: '男',
              itemStyle: {
                color: '#5470C6'
              } // 自定义颜色
            }, {
              value: data.female_count,
              name: '女',
              itemStyle: {
                color: '#EE6666'
              } // 自定义颜色
            }]
          }]
        };
        chart.setOption(option);

        // 响应式调整大小
        const resizeHandler = () => chart.resize();
        window.addEventListener('resize', resizeHandler);

        // 组件卸载时移除监听器
        onUnmounted(() => {
          window.removeEventListener('resize', resizeHandler);
          chart.dispose();
        });
      } catch (error) {
        console.error('获取性别分布数据失败:', error);
      }
    };
    onMounted(() => {
      renderGenderChart();
    });
    const __returned__ = {
      genderChart,
      renderGenderChart,
      ref,
      onMounted,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      },
      get API_CONFIG() {
        return API_CONFIG;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
